ROOT=[dict(id='C0903',meaning='眼睛；看；视觉',core='ops-/opt-：把东西看进眼里；既能成为光学与视力词，也能变成“综观内容”的词。',image='一条线追问怎样看清：optic → optical → optics；另一条线改变看的方式：亲自看是 autopsy 的早期含义，一起看全貌是 synopsis。',intro='希腊语的 ops“眼”、opsis“观看”和 optikos“视觉的”属于这一族。英语借入的层次并不相同：有词经过拉丁、法语，也有近代人用希腊成分新造的专业词。',forms='-opsy 接观看；opt- 常见于光学。syn- 把部分合看，auto- 强调亲自，pan- 强调全部。myopia 的 my- 接眯起、闭拢，不是英语 my。',branches=[['眼睛、光与专业服务','optic、optical、optics、optically、optician、optometry、optometrist、diopter'],['亲自查看与看清整体','autopsy、biopsy、synopsis、synoptic、panopticon'],['看不清远处及神话用名','myopia、myopic、diplopia、cyclops']],contrasts='opt 不表示所有词里的“选择”：optical 与 option 不属同一直接词源。synopsis 不是 microscope 一类仪器，而是把内容合起来看的概要。autopsy 与 biopsy 的检查对象也不同。',practice='用 synopsis 写一份作品梗概，用 myopic 评论一项只顾眼前的决定，再说明 optician 与 optometrist 的侧重点。',words=[w for w in family if w not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/optic','https://www.etymonline.com/word/optics','https://www.etymonline.com/word/autopsy','https://www.etymonline.com/word/myopia'])]
assert {x['word'] for x in W}==set(family)-shared-set(excluded)
assert len(W)==len({x['word'] for x in W}) and all(x['word'] in m['owned_words'] for x in W)
for x in W:
 assert len(x['examples'])>=2 and all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in x['history']),x['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_85_ops.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
